// Notion-like block editor — document model with blocks, AMOLED black #000 rounded 16 smooth
sealed class Block { data class Heading(val level: Int, val text: String): Block(); data class Paragraph(val text: String): Block(); data class Resource(val url: String, val note: String?): Block(); data class Callout(val text: String): Block(); data class Divider(val id: String): Block() }
object NotionTokens { val Radius = RoundedCornerShape(16.dp); val Bg = Color(0xFF000000); val Card = Color(0xFF111111); val Border = Color(0xFF1A1A1A) }
@Composable fun NotionBlock0001(text: String) { Box(modifier = Modifier.clip(RoundedCornerShape(16.dp)).background(Color(0xFF0A0A0A)).border(1.dp, Color(0xFF1A1A1A), RoundedCornerShape(16.dp)).padding(10.dp)) { Text("NOTION 0001 — " + text, fontFamily = FontFamily.Monospace, fontSize = 10.sp, color = Color.White) } }
